import { useSyncExternalStore } from 'react';
export function createPromiseHook(createPromise) {
    // Cached state
    let cachedResult;
    const listeners = new Set();
    const promise = createPromise();
    // Listen to Promise completion
    promise
        .then((result) => {
        cachedResult = result;
        const currentListeners = Array.from(listeners);
        listeners.clear();
        for (const listener of currentListeners) {
            listener();
        }
    })
        .catch((error) => {
        throw error;
    });
    // Subscribe adds local listener to `Set`
    function subscribe(onStoreChange) {
        if (cachedResult != null) {
            // We already have a cached result - no need to subscribe to anything
            return () => { };
        }
        listeners.add(onStoreChange);
        return () => {
            listeners.delete(onStoreChange);
        };
    }
    // Snapshot returns cached state
    function getSnapshot() {
        return cachedResult;
    }
    // This is the actual hook
    return () => {
        return useSyncExternalStore(subscribe, getSnapshot);
    };
}
